import {Component, OnInit} from '@angular/core';
import {AuthService} from '../auth/auth.service';

@Component({
  selector: 'app-unauthorized-login-method',
  templateUrl: './unauthorized-login-method.component.html',
  styleUrls: ['./unauthorized-login-method.component.scss']
})
export class UnauthorizedLoginMethodComponent implements OnInit {
  redirecturl = '';
  constructor(
      private authService: AuthService
  ) { }

  ngOnInit(): void {
    if (this.authService.isEmployee()) {
      this.redirecturl = '/#/secure/employee';
    } else {
      this.redirecturl = '#/logout';
    }
  }

}
